def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md."""
    if not isinstance(width, int) or width < 1:
        raise ValueError("width must be an int of at least 1")
    if len(indent) >= width:
        raise ValueError("indent must be shorter than width")

    paragraphs = text.split("\n")
    result = []

    for para in paragraphs:
        words = para.split()

        if not words:
            result.append("")
            continue

        current_line = ""
        is_first_line = True
        word_index = 0

        while word_index < len(words):
            word = words[word_index]
            line_indent = "" if is_first_line else indent
            available_width = width - len(line_indent)

            if current_line == "":
                if len(word) <= available_width:
                    current_line = word
                    word_index += 1
                else:
                    result.append(line_indent + word[:available_width])
                    words[word_index] = word[available_width:]
                    is_first_line = False
            else:
                if len(current_line) + 1 + len(word) <= available_width:
                    current_line += " " + word
                    word_index += 1
                else:
                    result.append(line_indent + current_line)
                    current_line = ""
                    is_first_line = False

        if current_line:
            line_indent = "" if is_first_line else indent
            result.append(line_indent + current_line)

    return result
